function syncControls(){const s=state.settings;$('baseSelect').value=s.base;$('photoEnabled').checked=s.photoEnabled;$('topoEnabled').checked=s.topoEnabled;$('topoSelect').value=s.topo;$('ringsEnabled').checked=s.rings;$('campLines').checked=s.campLines;$('wrapM').value=String(s.wrapM).replace('.',',');$('ringsM').value=s.ringsM.join(' ');for(const[k,input,label]of [['photoOpacity','photoOpacity','photoValue'],['topoOpacity','topoOpacity','topoValue'],['bathOpacity','bathOpacity','bathValue'],['split','swipeRange','swipeValue']]){$(input).value=s[k];$(label).textContent=`${Math.round(s[k])} %`;}$$('[data-photo]').forEach(e=>e.classList.toggle('active',e.dataset.photo===s.photo));$$('[data-compare]').forEach(e=>e.classList.toggle('active',e.dataset.compare===s.compare));$('swipeControls').hidden=s.compare!=='swipe';$('comparisonHint').textContent=s.compare==='topoSwipe'?'La cortina muestra el plano histórico a la izquierda. Debajo, el satélite actual mezclado con la foto histórica: ajusta la mezcla con la opacidad de la fotografía.':s.compare==='blend'?'Ajusta la opacidad de fotografía y plano. Con el 100 % la capa superior oculta la inferior.':s.compare==='modern'?'Solo se muestra el mapa actual y tus datos. La configuración histórica se conserva.':'Arrastra el separador sobre el mapa. Puedes mostrar fotografía y plano a la vez.';$('bathOpacityWrap').hidden=!state.bath;if(state.bath){$('bathName').value=state.bath.title;$('bathUrl').value=state.bath.url;$('bathLayer').value=state.bath.layer;$('bathVersion').value=state.bath.version;$('bathCredit').value=state.bath.credit;$('bathAllowed').checked=true;}}
