function renderFeatures(){const points=state.features.filter(f=>f.geometry.type==='Point'),traces=state.features.filter(f=>f.geometry.type==='LineString'),camp=activeCamp();$('pointsCount').textContent=points.length;const rings=state.settings.ringsM.map(m=>`${m} m`).join(', ');$('campSummary').textContent=camp?`Puesto activo: ${camp.properties.name}. Radios: ${rings}.`:`Marca un puesto para ver los radios (${rings}), las distancias en vueltas y el rumbo a cada punto.`;
 $('pointsList').innerHTML=points.length?points.map(f=>{const p=f.properties,c=f.geometry.coordinates,d=camp&&camp.id!==f.id?fmtFromCamp(camp.geometry.coordinates,c).text:null;return `<article class="point-card"><div class="row between"><h3>${esc(p.name)}</h3><span class="pill" style="color:${KINDS[p.kind][1]}">${esc(KINDS[p.kind][0])}</span></div><div class="meta">${c[1].toFixed(6)}, ${c[0].toFixed(6)}${d!==null?`<br><span style="color:var(--accent)">Desde el puesto: ${d}</span>`:''}${p.landmark?`<br>Alineación: ${esc(p.landmark)}`:''}${p.bottom?`<br>Fondo: ${esc(BOTTOMS[p.bottom])}`:''}${p.depth_m!==null?`<br>Profundidad registrada: ${p.depth_m.toFixed(2).replace('.',',')} m`:''}<br>${esc(p.verified?'Contrastado en campo':'Pendiente de contrastar')}${p.log?.length?` · ${p.log.length} nota${p.log.length>1?'s':''}`:''}</div><div class="row"><button data-view-point="${esc(f.id)}">Ver</button><button data-edit-point="${esc(f.id)}">Editar</button>${p.kind!=='camp'?`<button data-aim-point="${esc(f.id)}">Apuntar</button>`:''}${p.kind==='camp'?`<button data-active-camp="${esc(f.id)}">${camp?.id===f.id?'Puesto activo':'Activar'}</button>`:''}</div></article>`;}).join(''):`<div class="empty"><svg class="icon"><use href="#i-pin"/></svg>Aún no hay puntos guardados.<br>Marca tu puesto y empieza a registrar lo que observes.</div>`;
 updateBackupReminder();renderSession();renderWeather();$('tracesList').innerHTML=traces.map(f=>`<article class="point-card"><h3>${esc(f.properties.name)}</h3><div class="meta">${fmtDist(pathLength(f.geometry.coordinates))} · ${fmtWraps(pathLength(f.geometry.coordinates))} · ${f.geometry.coordinates.length} vértices</div><div class="row"><button data-view-trace="${esc(f.id)}">Ver</button><button data-delete-trace="${esc(f.id)}" class="danger">Eliminar</button></div></article>`).join('');map?.render(false);}
// Modo Apuntar: compara el rumbo al punto con la brújula del móvil (iOS: webkitCompassHeading, con permiso).
let aim=null;
function aimOrigin(){return gps?{coords:gps.coords,label:'desde tu posición GPS'}:activeCamp()?{coords:activeCamp().geometry.coordinates,label:'desde el puesto'}:null;}
// Brújula compartida por «Apuntar» y el modo Orientación.
const hdg={value:null,acc:null,listening:false};let compassMode=false;
function onOrient(e){let h=null,acc=null;if(typeof e.webkitCompassHeading==='number'&&e.webkitCompassHeading>=0){h=e.webkitCompassHeading;acc=e.webkitCompassAccuracy;}else if(e.absolute&&e.alpha!==null){h=(360-e.alpha)%360;}if(h===null)return;if(hdg.value===null)hdg.value=h;else{const d=((h-hdg.value+540)%360)-180;hdg.value=(hdg.value+d*.25+360)%360;}hdg.acc=acc;if(aim)updateAim();if(compassMode){$('compassBtn').style.setProperty('--north',`${-hdg.value}deg`);map.render(false);}}
async function askCompass(){try{if(typeof DeviceOrientationEvent!=='undefined'&&typeof DeviceOrientationEvent.requestPermission==='function'&&await DeviceOrientationEvent.requestPermission()!=='granted'){toast('Sin permiso de movimiento y orientación: la brújula no funcionará. Revisa los ajustes de Safari.',true);return false;}}catch{}if(!hdg.listening){hdg.listening=true;hdg.value=null;window.addEventListener('deviceorientationabsolute',onOrient);window.addEventListener('deviceorientation',onOrient);}return true;}
function releaseCompass(){if(aim||compassMode||!hdg.listening)return;hdg.listening=false;hdg.value=null;window.removeEventListener('deviceorientationabsolute',onOrient);window.removeEventListener('deviceorientation',onOrient);}
function compassOrigin(){return aimOrigin()||{coords:map.center,label:'desde el centro del mapa'};}
async function toggleCompass(){if(compassMode){compassMode=false;$('compassBtn').classList.remove('active');$('compassBtn').style.removeProperty('--north');$('headingBadge').hidden=true;releaseCompass();map.render(false);return;}if(!await askCompass())return;compassMode=true;$('compassBtn').classList.add('active');$('headingBadge').hidden=false;$('headingBadge').innerHTML='<strong>Esperando la brújula…</strong>';setTimeout(()=>{if(compassMode&&hdg.value===null)$('headingBadge').innerHTML='<strong>Brújula no disponible en este dispositivo</strong>';},2600);toast('Orientación activa: el haz muestra hacia dónde apuntas. Sujeta el móvil plano.');map.render(false);}
function headingVectors(){if(!compassMode||hdg.value===null)return '';const o=compassOrigin(),h=hdg.value,spread=clamp(hdg.acc>0?hdg.acc:8,4,20),L=800,p0=map.project(o.coords);let s=`<path d="M${p0[0].toFixed(1)},${p0[1].toFixed(1)}L${[...Array(9)].map((_,i)=>map.project(destination(o.coords,L,h-spread+i*spread/4)).map(v=>v.toFixed(1)).join(',')).join('L')}Z" fill="#e2c587" fill-opacity=".13" stroke="#e2c587" stroke-opacity=".35"/>`;const end=map.project(destination(o.coords,L,h));s+=`<line x1="${p0[0]}" y1="${p0[1]}" x2="${end[0]}" y2="${end[1]}" stroke="#f3ead6" stroke-width="2"/>`;
 for(let m=50;m<=L;m+=50){const q=destination(o.coords,m,h),c=map.project(q),a=map.project(destination(q,6,h+90)),b=map.project(destination(q,6,h-90));s+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#f3ead6" stroke-width="${m%100?1:2}"/>`;if(m%100===0&&Math.hypot(c[0]-p0[0],c[1]-p0[1])>40)s+=`<text x="${c[0]+8}" y="${c[1]+4}" class="map-label sub">${m} m · ${(m/state.settings.wrapM).toFixed(0)} v</text>`;}
 const inLine=state.features.filter(f=>f.geometry.type==='Point'&&f.properties.kind!=='camp').map(f=>{const c=f.geometry.coordinates;return {f,d:distance(o.coords,c),delta:Math.abs(((bearing(o.coords,c)-h+540)%360)-180)};}).filter(x=>x.d>5&&x.d<=2000&&x.delta<=Math.max(4,spread/2)).sort((a,b)=>a.d-b.d);
 $('headingBadge').innerHTML=`<span class="wx-arrow small" style="transform:rotate(${h}deg)">↑</span><strong>${Math.round(h)}° ${cardinal(h)}</strong><span>${inLine.length?`En línea: ${esc(inLine[0].f.properties.name)} · ${fmtDist(inLine[0].d)}${inLine.length>1?` (+${inLine.length-1})`:''}`:o.label}</span>`;return s;}
async function startAim(id){if(!state.features.some(f=>f.id===id))return;if(!aimOrigin()){toast('Marca tu puesto o activa el GPS para saber desde dónde apuntar.',true);return;}
 await askCompass();
 aim={id,aligned:false,started:Date.now()};closeSidebar();$('aimPanel').hidden=false;$('gpsMark').hidden=true;updateAim();setTimeout(updateAim,2600);}
function stopAim(){aim=null;releaseCompass();$('aimPanel').hidden=true;$('gpsMark').hidden=!gps||mode!=='pan';}
function updateAim(){if(!aim)return;const f=state.features.find(x=>x.id===aim.id),o=aimOrigin();if(!f||!o){stopAim();return;}const c=f.geometry.coordinates,target=bearing(o.coords,c),d=distance(o.coords,c);
 $('aimName').textContent=f.properties.name;$('aimInfo').textContent=`${fmtDist(d)} · ${fmtWraps(d)} · rumbo ${Math.round(target)}° ${cardinal(target)} · ${o.label}`;const box=$('aimPanel');
 if(hdg.value===null){$('aimArrow').style.transform=`rotate(${target}deg)`;box.classList.remove('aligned');$('aimText').textContent=Date.now()-aim.started>2500?'Brújula no disponible':'Esperando la brújula…';$('aimSub').textContent=Date.now()-aim.started>2500?`Orienta el rumbo ${Math.round(target)}° con tu marca de la orilla. La flecha indica la dirección respecto al norte.`:'Sujeta el móvil plano, con la parte de arriba hacia el agua.';return;}
 const delta=((target-hdg.value+540)%360)-180,ok=Math.abs(delta)<=3;$('aimArrow').style.transform=`rotate(${delta}deg)`;box.classList.toggle('aligned',ok);if(ok&&!aim.aligned)navigator.vibrate?.(60);aim.aligned=ok;
 $('aimText').textContent=ok?'En línea ✓':`Gira ${Math.round(Math.abs(delta))}° a la ${delta<0?'izquierda':'derecha'}`;const bad=hdg.acc!==null&&(hdg.acc<0||hdg.acc>20);$('aimSub').textContent=`Brújula ${Math.round(hdg.value)}°${hdg.acc>=0&&hdg.acc!==null?` · precisión ±${Math.round(hdg.acc)}°`:''}${bad?' · calibra: aléjate del metal y dibuja un 8 con el móvil':''}`;}
function setMode(next){if(mode==='measure'&&draft.length>1&&next!=='measure'&&!confirm('El trazado no está guardado. ¿Descartarlo?'))return;mode=next;draft=[];closeSidebar();$('map').classList.toggle('tool',mode!=='pan');for(const[id,m]of [['addPoint','point'],['setCamp','camp'],['measureBtn','measure']])$(id).classList.toggle('active',mode===m);$('actionBar').hidden=mode==='pan';$('gpsMark').hidden=!gps||mode!=='pan';$('undoMeasure').hidden=mode!=='measure';$('saveTrace').hidden=mode!=='measure';$('cancelTool').textContent=mode==='measure'?'Terminar':'Cancelar';updateAction();map?.render(false);}
function updateAction(){const t=mode==='measure'?`${draft.length?`${fmtDist(pathLength(draft))} · ${fmtWraps(pathLength(draft))}`:'Medir un recorrido'}<small>Toca el mapa para añadir vértices. Guarda para conservarlo.</small>`:mode==='camp'?'Toca el mapa para colocar tu puesto.<small>Después podrás ajustar las coordenadas.</small>':mode==='sounding'?'Toca el lugar donde has medido con la sonda.<small>Indica la profundidad y su fecha en la ficha.</small>':'Toca el mapa para añadir un punto.<small>Selecciona su origen y añade tus notas.</small>';$('actionLabel').innerHTML=t;$('saveTrace').disabled=draft.length<2;$('undoMeasure').disabled=!draft.length;}
function onMapClick(c){if(mode==='measure'){draft.push(c);updateAction();map.render(false);return;}if(['point','camp','sounding'].includes(mode)){const kind=mode==='point'?'point':mode;openPoint(null,c,kind);mode='pan';$('actionBar').hidden=true;$('map').classList.remove('tool');for(const id of ['addPoint','setCamp','measureBtn'])$(id).classList.remove('active');}}
function updatePointInfo(){const camp=activeCamp(),c=[num($('pointLng').value),num($('pointLat').value)],id=$('pointId').value;$('pointFromCamp').textContent=!camp?'Marca un puesto para ver aquí la distancia en vueltas y el rumbo.':camp.id===id||$('pointKind').value==='camp'?'':coordOK(c)?`Desde el puesto «${camp.properties.name}»: ${fmtFromCamp(camp.geometry.coordinates,c).text}`:'';}
function openPoint(id,c,kind='point'){const f=id?state.features.find(x=>x.id===id):null;const p=f?.properties||{},coords=f?.geometry.coordinates||c||map.center;const suggested=state.settings.compare==='modern'?'manual':state.settings.topoEnabled?state.settings.topo:state.settings.photoEnabled?state.settings.photo:'manual';$('pointId').value=id||'';$('pointTitle').textContent=f?'Editar punto':kind==='camp'?'Marcar puesto':kind==='sounding'?'Registrar profundidad':'Nuevo punto';$('pointName').value=p.name||(kind==='camp'?'Mi puesto':kind==='sounding'?`Sonda ${state.features.filter(x=>x.properties.kind==='sounding').length+1}`:`${kind==='point'?'Punto':KINDS[kind][0]} ${state.features.filter(x=>x.geometry.type==='Point').length+1}`);$('pointKind').value=p.kind||kind;$('pointSource').value=p.source||(kind==='sounding'?'sonar':kind==='camp'?'manual':suggested);$('pointLat').value=coords[1].toFixed(6);$('pointLng').value=coords[0].toFixed(6);$('pointDepth').value=p.depth_m??'';$('pointDate').value=p.observedAt||today();$('pointWater').value=p.waterReference||'';$('pointNotes').value=p.notes||'';$('pointLandmark').value=p.landmark||'';$('pointBottom').value=p.bottom||'';$('useGps').hidden=!gps;updatePointInfo();$('pointVerified').checked=p.verified||false;$('deletePoint').hidden=!f;$('aimFromDialog').hidden=!f||p.kind==='camp';$('pointDialog').showModal();setTimeout(()=>$('pointName').focus(),50);}
$('pointForm').addEventListener('submit',e=>{e.preventDefault();const coords=[num($('pointLng').value),num($('pointLat').value)];if(!coordOK(coords)){toast('Revisa las coordenadas WGS84: latitud entre −85 y 85, longitud entre −180 y 180.',true);return;}const depth=$('pointDepth').value.trim()===''?null:num($('pointDepth').value);if(depth!==null&&(!Number.isFinite(depth)||depth<0||depth>500)){toast('Introduce una profundidad entre 0 y 500 metros, o deja el campo vacío.',true);return;}if(depth===null&&$('pointKind').value==='sounding'){toast('Una medición de sonda necesita la profundidad.',true);return;}if(depth!==null&&!$('pointDate').value){toast('Añade la fecha de la medición de profundidad.',true);return;}const id=$('pointId').value||uid(),old=state.features.find(f=>f.id===id),now=new Date().toISOString();const f={type:'Feature',id,geometry:{type:'Point',coordinates:coords},properties:{name:$('pointName').value.trim()||'Sin nombre',kind:$('pointKind').value,landmark:$('pointLandmark').value.trim(),bottom:$('pointBottom').value,source:$('pointSource').value,depth_m:depth,observedAt:$('pointDate').value,waterReference:$('pointWater').value.trim(),notes:$('pointNotes').value.trim(),verified:$('pointVerified').checked,log:old?.properties.log||[],createdAt:old?.properties.createdAt||now,updatedAt:now}};if(old)state.features[state.features.indexOf(old)]=f;else state.features.push(f);if(f.properties.kind==='camp'&&!activeCamp())state.activeCampId=id;if(f.properties.kind==='camp'&&!state.activeCampId)state.activeCampId=id;save();renderFeatures();if(f.properties.kind==='camp')loadWeather();$('pointDialog').close();toast('Punto guardado en este navegador.');});
$('aimFromDialog').addEventListener('click',()=>{const id=$('pointId').value;if(!id){toast('Guarda el punto antes de apuntar.',true);return;}$('pointDialog').close();startAim(id);});
$('deletePoint').addEventListener('click',()=>{const id=$('pointId').value,f=state.features.find(f=>f.id===id);if(!f||!confirm(`¿Eliminar «${f.properties.name}»?`))return;state.features=state.features.filter(f=>f.id!==id);if(state.activeCampId===id)state.activeCampId=null;save();renderFeatures();$('pointDialog').close();});
async function backup(){const payload={app:'orellana-atlas',schemaVersion:1,exportedAt:new Date().toISOString(),...state};if(!await shareOrDownload(`Orellana_Atlas_${today()}.json`,JSON.stringify(payload,null,2),'application/json','Copia de Carp Field Notes'))return;state.lastBackupAt=new Date().toISOString();save();updateBackupReminder();toast('Copia completa exportada. Guárdala en Archivos o iCloud.');}
// Recordatorio: hay cambios sin copia desde hace más de 3 días (o nunca se hizo una).
function needsBackup(){const stamps=[...state.features.map(f=>Date.parse(f.properties.updatedAt)||0),...state.catches.map(c=>Date.parse(c.at)||0)];if(!stamps.length)return false;const last=Date.parse(state.lastBackupAt||0)||0,first=Math.min(...state.features.map(f=>Date.parse(f.properties.createdAt)||Date.now()),...state.catches.map(c=>Date.parse(c.at)||Date.now()));return Math.max(...stamps)>last&&Date.now()-Math.max(last,first)>3*864e5;}
function updateBackupReminder(){const n=needsBackup();for(const id of ['exportTop','backupBtn'])$(id).classList.toggle('attention',n);$('backupHint').hidden=!n;}
async function sharePoints(){const text=JSON.stringify({type:'FeatureCollection',name:'Carp Field Notes · compartido',features:state.features},null,2);if(await shareOrDownload(`Orellana_compartir_${today()}.geojson`,text,'application/geo+json','Puntos de Carp Field Notes'))toast('Tu compañero puede importarlo en «Importar». Los puntos repetidos se actualizan, no se duplican.');}
function exportGeo(){download(`Orellana_puntos_trazados_${today()}.geojson`,JSON.stringify({type:'FeatureCollection',name:'Carp Field Notes',features:state.features},null,2),'application/geo+json');}
function exportGPX(){const point=(f)=>{const p=f.properties,c=f.geometry.coordinates;const desc=[p.notes,p.depth_m!==null?`Profundidad registrada: ${p.depth_m} m`:'',p.observedAt?`Fecha: ${p.observedAt}`:'',p.waterReference?`Referencia agua: ${p.waterReference}`:'',`Origen: ${p.source}`].filter(Boolean).join('\n');return `<wpt lat="${c[1]}" lon="${c[0]}"><name>${esc(p.name)}</name><desc>${esc(desc)}</desc><type>${esc(p.kind)}</type><extensions><oa:source>${esc(p.source)}</oa:source>${p.depth_m!==null?`<oa:depth_m>${p.depth_m}</oa:depth_m>`:''}<oa:observedAt>${esc(p.observedAt)}</oa:observedAt><oa:waterReference>${esc(p.waterReference)}</oa:waterReference>${p.landmark?`<oa:landmark>${esc(p.landmark)}</oa:landmark>`:''}${p.bottom?`<oa:bottom>${esc(p.bottom)}</oa:bottom>`:''}</extensions></wpt>`;};const tracks=state.features.filter(f=>f.geometry.type==='LineString').map(f=>`<trk><name>${esc(f.properties.name)}</name><desc>${esc(f.properties.notes)}</desc><trkseg>${f.geometry.coordinates.map(c=>`<trkpt lat="${c[1]}" lon="${c[0]}"/>`).join('')}</trkseg></trk>`);const xml=`<?xml version="1.0" encoding="UTF-8"?>\n<gpx version="1.1" creator="Carp Field Notes" xmlns="http://www.topografix.com/GPX/1/1" xmlns:oa="urn:orellana-atlas:1"><metadata><name>Carp Field Notes</name><time>${new Date().toISOString()}</time></metadata>${state.features.filter(f=>f.geometry.type==='Point').map(point).join('')}${tracks.join('')}</gpx>`;download(`Orellana_${today()}.gpx`,xml,'application/gpx+xml');}
function parseGPX(text){const doc=new DOMParser().parseFromString(text,'text/xml');if(doc.querySelector('parsererror'))throw Error('El GPX no es XML válido.');const children=(e,tag)=>Array.from(e.children).find(c=>c.localName===tag)?.textContent||'';const ext=(e,tag)=>Array.from(e.getElementsByTagNameNS('*',tag))[0]?.textContent||'';const f=[];for(const w of Array.from(doc.getElementsByTagNameNS('*','wpt'))){f.push({type:'Feature',geometry:{type:'Point',coordinates:[num(w.getAttribute('lon')),num(w.getAttribute('lat'))]},properties:{name:children(w,'name'),kind:children(w,'type'),notes:children(w,'desc'),source:ext(w,'source')||'import',depth_m:ext(w,'depth_m')||null,observedAt:ext(w,'observedAt'),waterReference:ext(w,'waterReference'),landmark:ext(w,'landmark'),bottom:ext(w,'bottom')}});}for(const tag of ['trkseg','rte'])for(const t of Array.from(doc.getElementsByTagNameNS('*',tag))){const pts=Array.from(t.getElementsByTagNameNS('*',tag==='rte'?'rtept':'trkpt')).map(p=>[num(p.getAttribute('lon')),num(p.getAttribute('lat'))]);f.push({type:'Feature',geometry:{type:'LineString',coordinates:pts},properties:{name:children(tag==='rte'?t:t.parentElement,'name')||'Trazado GPX',notes:children(tag==='rte'?t:t.parentElement,'desc'),source:'import'}});}return f;}
$('fileInput').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('El archivo supera el límite de 5 MB.');const text=await file.text();let data,arr,replace=false;if(file.name.toLowerCase().endsWith('.gpx')||text.trim().startsWith('<'))arr=parseGPX(text);else{data=JSON.parse(text);if(data.app==='orellana-atlas'&&data.schemaVersion===1){if(!confirm('Restaurar esta copia sustituirá los puntos, trazados y ajustes actuales. ¿Continuar?'))return;replace=true;arr=data.features;}else if(data.type==='FeatureCollection')arr=data.features;else if(data.type==='Feature')arr=[data];else throw Error('Formato no reconocido. Usa una copia del atlas, GeoJSON o GPX.');}if(!Array.isArray(arr))throw Error('No se ha encontrado una lista de elementos válida.');if(arr.length>3000)throw Error('Máximo 3.000 elementos por proyecto.');const features=arr.map(normalizedFeature).filter(Boolean),rejected=arr.length-features.length;if(!features.length&&arr.length)throw Error('No hay puntos ni líneas con coordenadas WGS84 válidas.');if(replace){state={settings:normalizeSettings(data.settings),features,activeCampId:typeof data.activeCampId==='string'?data.activeCampId:null,bath:normalizeBath(data.bath),updatedAt:null,lastBackupAt:new Date().toISOString(),catches:normList(data.catches,normCatch,5000),rods:normList(data.rods,normRod,20),baitLog:normList(data.baitLog,normBait,5000)};setNight(state.settings.nightMode);map.setView(state.settings.center,state.settings.zoom);applySources();}else{if(state.features.length+features.length>3000)throw Error('El proyecto resultante supera los 3.000 elementos.');let added=0,updated=0,same=0;for(const f of features){const i=state.features.findIndex(x=>x.id===f.id);if(i<0){state.features.push(f);added++;}else if((Date.parse(f.properties.updatedAt)||0)>(Date.parse(state.features[i].properties.updatedAt)||0)){state.features[i]=f;updated++;}else same++;}features.summary=`${added} nuevos · ${updated} actualizados${same?` · ${same} ya estaban`:''}`;if(features.length){const coords=features.flatMap(f=>f.geometry.type==='Point'?[f.geometry.coordinates]:f.geometry.coordinates);map.fit(coords);}}save();renderFeatures();selectTab('points');updateBackupReminder();toast(`${features.summary||`${features.length} elementos importados`}${rejected?` · ${rejected} incompatibles omitidos`:''}.`,rejected>0);}catch(err){toast(err.message||'No se ha podido importar el archivo.',true);}});
// ===== Sesión de pesca: tiempo (Open-Meteo), sol y luna, capturas, cañas y recebado =====
const HOUR=36e5,pad2=n=>String(n).padStart(2,'0');
const hhmm=t=>{const d=new Date(t);return `${pad2(d.getHours())}:${pad2(d.getMinutes())}`;};
const dayName=t=>new Date(t).toLocaleDateString('es-ES',{weekday:'short',day:'numeric'});
const localDT=t=>{const d=new Date(t);return `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}T${pad2(d.getHours())}:${pad2(d.getMinutes())}`;};
const fmtKg=w=>`${Number(w.toFixed(3)).toString().replace('.',',')} kg`;
const fmtAgo=t=>{const m=Math.round((Date.now()-t)/6e4);return m<1?'ahora':m<60?`hace ${m} min`:`hace ${Math.floor(m/60)} h ${pad2(m%60)} min`;};
const fmtIn=ms=>{const m=Math.ceil(ms/6e4);return m<60?`${m} min`:`${Math.floor(m/60)} h ${pad2(m%60)} min`;};
const signed=(v,d=1)=>`${v>0?'+':v<0?'−':'±'}${Math.abs(v).toFixed(d).replace('.',',')}`;
// --- Astronomía (algoritmos de baja precisión tipo SunCalc; error de pocos minutos) ---
const J1970=2440588,J2000=2451545,OBL=DEG*23.4397;
const toDays=t=>t/864e5-.5+J1970-J2000;
