function wxVal(key,t){if(!wx)return null;const a=wx[key],ts=wx.t;if(!a||t<ts[0]||t>ts[ts.length-1])return null;let i=Math.min(ts.length-2,Math.max(0,Math.floor((t-ts[0])/HOUR)));while(i>0&&ts[i]>t)i--;while(i<ts.length-2&&ts[i+1]<t)i++;const v0=a[i],v1=a[i+1];if(!Number.isFinite(v0))return Number.isFinite(v1)?v1:null;if(!Number.isFinite(v1))return v0;if(key==='dir')return (t-ts[i])<(ts[i+1]-t)?v0:v1;return v0+(v1-v0)*(t-ts[i])/(ts[i+1]-ts[i]);}
