 let s=`<svg viewBox="0 0 ${W} ${H}" class="wx-chart" role="img" aria-label="Presión atmosférica de los últimos 3 días y los próximos días">`;for(let d=new Date(t0).setHours(24,0,0,0);d<t1;d+=864e5)s+=`<line x1="${X(d)}" y1="8" x2="${X(d)}" y2="${H-22}" stroke="#3b3125"/><text x="${X(d)+3}" y="${H-8}" class="wx-tick">${esc(dayName(d))}</text>`;
 s+=`<path d="${idx.map((i,k)=>`${k?'L':'M'}${X(wx.t[i]).toFixed(1)},${Y(wx.p[i]).toFixed(1)}`).join('')}" fill="none" stroke="#c9a45c" stroke-width="2"/>`;if(now>t0&&now<t1)s+=`<line x1="${X(now)}" y1="6" x2="${X(now)}" y2="${H-22}" stroke="#f3ead6" stroke-dasharray="3 3"/><text x="${X(now)+3}" y="16" class="wx-tick" style="fill:#f3ead6">ahora</text>`;
