 for(let k=0;k<9;k++){const y=58+k*k*2.6,w=40+k*12,x=(k*67)%300;s+=`<path d="M${x} ${y}h${w}" stroke="#e2c587" stroke-opacity="${(.16-k*.012).toFixed(3)}" stroke-width="${(.8+k*.12).toFixed(2)}"/>`;}
 for(const [x0,dir] of [[350,-1],[10,1]])for(let k=0;k<7;k++){const bx=x0+dir*k*6,h=120+((k*37)%70);s+=`<path d="M${bx} ${H}C${bx-dir*4} ${H-h*.5} ${bx+dir*(8+k*3)} ${H-h*.8} ${bx+dir*(18+k*4)} ${H-h}" stroke="#4a3c22" stroke-width="${3-k*.25}" fill="none" stroke-linecap="round" opacity=".85"/>`;}
