  s+=`<g class="pod-rod ${st}" data-pod-rod="${esc(r.id)}" tabindex="0" role="button" aria-label="${esc(r.name)}"><path d="M${x} ${yPod+8}V${H}" stroke="#14110c" stroke-width="7"/>`;
  s+=`<rect x="${x-aw/2}" y="${yPod-44}" width="${aw}" height="46" rx="7" fill="#0b0a08" stroke="#a8a69e" stroke-opacity=".5"/>`;for(const dx of [-aw/2+8,aw/2-8])for(const dy of [-34,-24,-14])s+=`<circle cx="${x+dx}" cy="${yPod+dy}" r="2.4" class="pod-led" fill="${led}"/>`;
  [.52,.64,.74,.82,.89].forEach(t=>{const y=yb-(yb-yt)*t,rr=Math.max(2.5,15*(1-t)+1.5);s+=`<circle cx="${X(i,y)}" cy="${y+rr+1.5}" r="${rr}" fill="none" stroke="#a8a69e" stroke-opacity=".75" stroke-width="${(1.6*(1-t)+.6).toFixed(2)}"/>`;});
