function openTutorial(){tutIndex=0;tutBusy=false;tutPages().forEach((p,i)=>{p.className='tut-page'+(i?'':' active');});tutDraw(tutPages()[0]);tutNav();closeSidebar();if(!$('tutorial').open)$('tutorial').showModal();}
